public class EnrollmentRequestModel
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int SelectedCourseId { get; set; }
    public string? Comments { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    List<Department> GetDepartments();
    List<Course> GetAllCourses();
    List<Course> GetFeaturedCourses();
    List<Course> GetCoursesByDepartment(int departmentId);
    Course? GetCourseById(int id);
    List<Course> SearchCourses(string? searchTerm, int? departmentId, int? credits);
    bool SubmitEnrollmentRequest(EnrollmentRequestModel request);
}

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Pure and applied mathematical sciences." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Literature, writing, and language studies." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and human civilization." },
        };

        var instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor", Bio = "Dr. Chen specializes in algorithms and data structures with over 15 years of teaching experience. She has published extensively in computational complexity.", Email = "achen@university.edu", Office = "CS Building, Room 312" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor", Bio = "Dr. Martinez focuses on artificial intelligence and machine learning. He leads the university's AI research lab.", Email = "rmartinez@university.edu", Office = "CS Building, Room 205" },
            new() { Id = 3, Name = "Dr. Sarah Johnson", Title = "Professor", Bio = "Dr. Johnson is a specialist in abstract algebra and number theory with multiple award-winning publications.", Email = "sjohnson@university.edu", Office = "Math Hall, Room 401" },
            new() { Id = 4, Name = "Dr. James Wilson", Title = "Assistant Professor", Bio = "Dr. Wilson researches quantum mechanics and particle physics. He joined the faculty after postdoctoral work at CERN.", Email = "jwilson@university.edu", Office = "Science Center, Room 118" },
            new() { Id = 5, Name = "Prof. Emily Davis", Title = "Professor", Bio = "Prof. Davis is an acclaimed author and literary critic specializing in 20th-century American literature.", Email = "edavis@university.edu", Office = "Humanities Building, Room 220" },
            new() { Id = 6, Name = "Dr. Michael Brown", Title = "Associate Professor", Bio = "Dr. Brown researches modern European history with a focus on the World Wars era.", Email = "mbrown@university.edu", Office = "Humanities Building, Room 315" },
            new() { Id = 7, Name = "Dr. Lisa Park", Title = "Professor", Bio = "Dr. Park specializes in software engineering and distributed systems. She consults for major tech companies.", Email = "lpark@university.edu", Office = "CS Building, Room 410" },
            new() { Id = 8, Name = "Dr. David Kim", Title = "Associate Professor", Bio = "Dr. Kim focuses on statistical methods and probability theory with applications in data science.", Email = "dkim@university.edu", Office = "Math Hall, Room 302" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering fundamental concepts including problem-solving, algorithms, data representation, and an introduction to programming using Python.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "CS Building, Room 101", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = instructors[0], IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, CourseCode = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Location = "CS Building, Room 203", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = instructors[0], IsFeatured = true, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 3, CourseCode = "CS 330", Title = "Artificial Intelligence", Description = "Introduction to the theory and practice of artificial intelligence. Topics include search algorithms, knowledge representation, machine learning fundamentals, and neural networks.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "CS Building, Room 305", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = instructors[1], IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 44 },
            new() { Id = 4, CourseCode = "CS 410", Title = "Software Engineering", Description = "Principles and practices of software engineering including requirements analysis, design patterns, testing methodologies, agile development, and project management.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "CS Building, Room 410", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = instructors[6], IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 32 },
            new() { Id = 5, CourseCode = "MATH 151", Title = "Calculus I", Description = "Introduction to differential calculus. Topics include limits, continuity, derivatives, and applications of differentiation to real-world problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Hall, Room 100", DepartmentId = 2, DepartmentName = "Mathematics", Instructor = instructors[2], IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 130 },
            new() { Id = 6, CourseCode = "MATH 251", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of equations.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Math Hall, Room 205", DepartmentId = 2, DepartmentName = "Mathematics", Instructor = instructors[2], IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 65 },
            new() { Id = 7, CourseCode = "MATH 360", Title = "Probability & Statistics", Description = "Introduction to probability theory and statistical methods. Covers random variables, distributions, hypothesis testing, regression, and applications in data analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Math Hall, Room 302", DepartmentId = 2, DepartmentName = "Mathematics", Instructor = instructors[7], IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 48 },
            new() { Id = 8, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Introduction to classical mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:50 PM", Location = "Science Center, Room 100", DepartmentId = 3, DepartmentName = "Physics", Instructor = instructors[3], IsFeatured = true, MaxEnrollment = 100, CurrentEnrollment = 85 },
            new() { Id = 9, CourseCode = "PHYS 301", Title = "Quantum Mechanics", Description = "Introduction to quantum mechanics covering wave-particle duality, the Schrödinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Science Center, Room 210", DepartmentId = 3, DepartmentName = "Physics", Instructor = instructors[3], IsFeatured = false, MaxEnrollment = 35, CurrentEnrollment = 28 },
            new() { Id = 10, CourseCode = "ENG 101", Title = "English Composition", Description = "Development of college-level writing skills through practice in expository and argumentative essays. Emphasis on clarity, structure, and critical thinking.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Humanities Building, Room 105", DepartmentId = 4, DepartmentName = "English", Instructor = instructors[4], IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 28 },
            new() { Id = 11, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of major works and movements in American literature from the colonial period to the present, with emphasis on cultural and historical contexts.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Location = "Humanities Building, Room 220", DepartmentId = 4, DepartmentName = "English", Instructor = instructors[4], IsFeatured = false, MaxEnrollment = 35, CurrentEnrollment = 22 },
            new() { Id = 12, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from ancient times through the late medieval period. Examines political, social, and cultural developments across major civilizations.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Humanities Building, Room 310", DepartmentId = 5, DepartmentName = "History", Instructor = instructors[5], IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 60 },
            new() { Id = 13, CourseCode = "HIST 320", Title = "Modern European History", Description = "Study of European history from the French Revolution to the present, focusing on political revolutions, industrialization, world wars, and the formation of the European Union.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Location = "Humanities Building, Room 315", DepartmentId = 5, DepartmentName = "History", Instructor = instructors[5], IsFeatured = false, MaxEnrollment = 45, CurrentEnrollment = 33 },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourseById(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId, int? credits)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (credits.HasValue && credits.Value > 0)
        {
            query = query.Where(c => c.Credits == credits.Value);
        }

        return query.ToList();
    }

    public bool SubmitEnrollmentRequest(EnrollmentRequestModel request)
    {
        // In a real app, this would persist to a database
        var course = GetCourseById(request.SelectedCourseId);
        return course is not null &&
               !string.IsNullOrWhiteSpace(request.StudentName) &&
               !string.IsNullOrWhiteSpace(request.StudentId);
    }
}

