@page "/"

@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="hero-section">
    <h1>University Course Catalog</h1>
    <p>Explore our departments and courses for the upcoming semester.</p>
    <a href="/catalog" class="btn-primary">Browse All Courses</a>
</div>

<section class="home-section">
    <h2>Departments</h2>
    <div class="department-grid">
        @foreach (var dept in departments)
        {
            <DepartmentLinkCard Department="dept" />
        }
    </div>
</section>

<section class="home-section">
    <h2>Featured Courses</h2>
    <div class="featured-grid">
        @foreach (var course in featuredCourses)
        {
            <FeaturedCourseCard Course="course" />
        }
    </div>
</section>

<section class="home-section enroll-cta">
    <h2>Ready to Enroll?</h2>
    <p>Submit your enrollment request for any available course.</p>
    <a href="/enroll" class="btn-primary">Request Enrollment</a>
</section>

@code {
    private List<Department> departments = new();
    private List<Course> featuredCourses = new();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        featuredCourses = CatalogService.GetFeaturedCourses();
    }
}

@page "/catalog"
@rendermode InteractiveServer

@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<CatalogFilters Departments="departments"
                SearchTerm="@searchTerm"
                SearchTermChanged="OnSearchTermChanged"
                DepartmentId="@departmentId"
                DepartmentIdChanged="OnDepartmentChanged"
                Credits="@credits"
                CreditsChanged="OnCreditsChanged" />

<p class="results-count">@filteredCourses.Count course(s) found</p>

@if (filteredCourses.Count == 0)
{
    <p class="no-results">No courses match your search criteria. Try adjusting your filters.</p>
}
else
{
    <div class="table-responsive">
        <table class="course-table">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th>Schedule</th>
                    <th>Enrollment</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in filteredCourses)
                {
                    <CourseListItem Course="course" />
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();
    private string? searchTerm;
    private int departmentId;
    private int credits;

    [SupplyParameterFromQuery]
    public int? DepartmentIdQuery { get; set; }

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        if (DepartmentIdQuery.HasValue)
        {
            departmentId = DepartmentIdQuery.Value;
        }
        ApplyFilters();
    }

    private void OnSearchTermChanged(string? value)
    {
        searchTerm = value;
        ApplyFilters();
    }

    private void OnDepartmentChanged(int value)
    {
        departmentId = value;
        ApplyFilters();
    }

    private void OnCreditsChanged(int value)
    {
        credits = value;
        ApplyFilters();
    }

    private void ApplyFilters()
    {
        filteredCourses = CatalogService.SearchCourses(searchTerm,
            departmentId > 0 ? departmentId : null,
            credits > 0 ? credits : null);
    }
}

@page "/enroll"

@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>

<nav class="breadcrumb">
    <a href="/">Home</a> &rsaquo;
    <span>Enrollment Request</span>
</nav>

@if (submitted)
{
    <div class="success-message">
        <h2>Request Submitted</h2>
        <p>Your enrollment request has been submitted successfully. You will receive a confirmation email at your university address.</p>
        <a href="/catalog" class="btn-primary">Back to Catalog</a>
    </div>
}
else
{
    <div class="enrollment-form-container">
        <p>Fill out the form below to request enrollment in a course. All fields are required unless marked optional.</p>

        <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
            <AntiforgeryToken />

            <div class="form-group">
                <label for="studentName">Full Name</label>
                <input id="studentName" type="text" name="Model.StudentName"
                       value="@Model.StudentName" required />
            </div>

            <div class="form-group">
                <label for="studentId">Student ID</label>
                <input id="studentId" type="text" name="Model.StudentId"
                       value="@Model.StudentId" required
                       placeholder="e.g., S12345678" />
            </div>

            <div class="form-group">
                <label for="courseSelect">Course</label>
                <select id="courseSelect" name="Model.SelectedCourseId" required>
                    <option value="">— Select a course —</option>
                    @foreach (var course in courses)
                    {
                        <option value="@course.Id" selected="@(course.Id == Model.SelectedCourseId)">
                            @course.CourseCode — @course.Title (@course.Credits cr.)
                        </option>
                    }
                </select>
            </div>

            <div class="form-group">
                <label for="comments">Comments (optional)</label>
                <textarea id="comments" name="Model.Comments" rows="4"
                          placeholder="Any additional information…">@Model.Comments</textarea>
            </div>

            @if (submitError)
            {
                <div class="error-message">
                    <p>There was a problem submitting your request. Please verify all fields and try again.</p>
                </div>
            }

            <button type="submit" class="btn-primary">Submit Request</button>
        </form>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequestModel Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private List<Course> courses = new();
    private bool submitted;
    private bool submitError;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetAllCourses();
        if (CourseId.HasValue && Model.SelectedCourseId == 0)
        {
            Model.SelectedCourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var success = CatalogService.SubmitEnrollmentRequest(Model);
        if (success)
        {
            submitted = true;
        }
        else
        {
            submitError = true;
        }
    }
}

