<PageTitle>University Course Catalog</PageTitle>

<div class="hero-section">
    <h1>University Course Catalog</h1>
    <p>Explore our departments and courses for the upcoming semester.</p>
    <a href="/catalog" class="btn-primary">Browse All Courses</a>
</div>

<section class="home-section">
    <h2>Departments</h2>
    <div class="department-grid">
        @foreach (var dept in departments)
        {
            <DepartmentLinkCard Department="dept" />
        }
    </div>
</section>

<section class="home-section">
    <h2>Featured Courses</h2>
    <div class="featured-grid">
        @foreach (var course in featuredCourses)
        {
            <FeaturedCourseCard Course="course" />
        }
    </div>
</section>

<section class="home-section enroll-cta">
    <h2>Ready to Enroll?</h2>
    <p>Submit your enrollment request for any available course.</p>
    <a href="/enroll" class="btn-primary">Request Enrollment</a>
</section>

@code {
    private List<Department> departments = new();
    private List<Course> featuredCourses = new();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        featuredCourses = CatalogService.GetFeaturedCourses();
    }
}

@page "/catalog"
@rendermode InteractiveServer

@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<CatalogFilters Departments="departments"
                SearchTerm="@searchTerm"
                SearchTermChanged="OnSearchTermChanged"
                DepartmentId="@departmentId"
                DepartmentIdChanged="OnDepartmentChanged"
                Credits="@credits"
                CreditsChanged="OnCreditsChanged" />

<p class="results-count">@filteredCourses.Count course(s) found</p>

@if (filteredCourses.Count == 0)
{
    <p class="no-results">No courses match your search criteria. Try adjusting your filters.</p>
}
else
{
    <div class="table-responsive">
        <table class="course-table">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th>Schedule</th>
                    <th>Enrollment</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in filteredCourses)
                {
                    <CourseListItem Course="course" />
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();
    private string? searchTerm;
    private int departmentId;
    private int credits;

    [SupplyParameterFromQuery]
    public int? DepartmentIdQuery { get; set; }

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        if (DepartmentIdQuery.HasValue)
        {
            departmentId = DepartmentIdQuery.Value;
        }
        ApplyFilters();
    }

    private void OnSearchTermChanged(string? value)
    {
        searchTerm = value;
        ApplyFilters();
    }

    private void OnDepartmentChanged(int value)
    {
        departmentId = value;
        ApplyFilters();
    }

    private void OnCreditsChanged(int value)
    {
        credits = value;
        ApplyFilters();
    }

    private void ApplyFilters()
    {
        filteredCourses = CatalogService.SearchCourses(searchTerm,
            departmentId > 0 ? departmentId : null,
            credits > 0 ? credits : null);
    }
}

