arguments.new_str:
html, body {
    font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
}

a, .btn-link {
    color: #006bb7;
}

.btn:focus, .btn:active:focus, .btn-link.nav-link:focus, .form-control:focus, .form-check-input:focus {
    box-shadow: 0 0 0 0.1rem white, 0 0 0 0.25rem #258cfb;
}

.content {
    padding-top: 1.1rem;
}

h1:focus {
    outline: none;
}

.blazor-error-boundary {
    background: url(data:image/svg+xml;base64,) no-repeat 1rem/1.8rem, #b32121;
    padding: 1rem 1rem 1rem 3.7rem;
    color: white;
}

    .blazor-error-boundary::after {
        content: "An error has occurred."
    }

/* ── Buttons ── */
.btn-primary {
    display: inline-block;
    padding: 0.6rem 1.4rem;
    background-color: #1b6ec2;
    color: #fff;
    border: none;
    border-radius: 6px;
    text-decoration: none;
    font-size: 1rem;
    cursor: pointer;
}
.btn-primary:hover { background-color: #155a9c; }

.btn-details {
    display: inline-block;
    padding: 0.35rem 0.8rem;
    background-color: #f0f0f0;
    color: #1b6ec2;
    border-radius: 4px;
    text-decoration: none;
    font-size: 0.875rem;
    border: 1px solid #ccc;
}
.btn-details:hover { background-color: #e0e0e0; }

/* ── Hero ── */
.hero-section {
    background: linear-gradient(135deg, #1b3a5c, #1b6ec2);
    color: #fff;
    padding: 3rem 2rem;
    border-radius: 10px;
    text-align: center;
    margin-bottom: 2rem;
}
.hero-section h1 { margin: 0 0 0.5rem; font-size: 2.2rem; }
.hero-section p { margin: 0 0 1.5rem; font-size: 1.1rem; opacity: 0.9; }
.hero-section .btn-primary { background-color: #fff; color: #1b3a5c; font-weight: 600; }
.hero-section .btn-primary:hover { background-color: #e8e8e8; }

/* ── Home sections ── */
.home-section { margin-bottom: 2.5rem; }
.home-section h2 { font-size: 1.5rem; margin-bottom: 1rem; color: #1b3a5c; }

.enroll-cta {
    background: #f7f9fc;
    padding: 2rem;
    border-radius: 10px;
    text-align: center;
}

/* ── Department grid ── */
.department-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 1rem;
}
.department-link-card {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 1.2rem;
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.15s;
}
.department-link-card:hover { box-shadow: 0 2px 8px rgba(0,0,0,0.12); }
.dept-code { font-size: 1.3rem; font-weight: 700; color: #1b6ec2; }
.dept-name { font-size: 0.9rem; margin-top: 0.3rem; color: #555; }

/* ── Featured courses grid ── */
.featured-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 1.2rem;
}
.featured-course-card {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.2rem;
    display: flex;
    flex-direction: column;
}
.featured-course-card .card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}
.course-code { font-weight: 700; color: #1b6ec2; }
.credits-badge {
    background: #e8f0fe;
    color: #1b6ec2;
    padding: 0.15rem 0.5rem;
    border-radius: 12px;
    font-size: 0.8rem;
    font-weight: 600;
}
.featured-course-card h3 { margin: 0 0 0.5rem; font-size: 1.1rem; }
.featured-course-card .course-description { color: #555; font-size: 0.9rem; flex: 1; }
.featured-course-card .card-meta { display: flex; flex-direction: column; gap: 0.2rem; font-size: 0.85rem; color: #666; margin-bottom: 0.8rem; }
.featured-course-card .card-footer { display: flex; justify-content: space-between; align-items: center; }
.enrollment-status { font-size: 0.85rem; color: #666; }

/* ── Catalog filters ── */
.catalog-filters {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f7f9fc;
    border-radius: 8px;
}
.filter-group { display: flex; flex-direction: column; flex: 1; min-width: 180px; }
.filter-group label { font-size: 0.85rem; font-weight: 600; margin-bottom: 0.3rem; color: #333; }
.filter-group input,
.filter-group select {
    padding: 0.5rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
}

.results-count { color: #666; font-size: 0.9rem; margin-bottom: 0.5rem; }
.no-results { color: #888; font-style: italic; }

/* ── Course table ── */
.table-responsive { overflow-x: auto; }
.course-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.95rem;
}
.course-table th, .course-table td {
    text-align: left;
    padding: 0.7rem 0.8rem;
    border-bottom: 1px solid #e8e8e8;
}
.course-table th {
    background: #f7f9fc;
    font-weight: 600;
    color: #333;
    position: sticky;
    top: 0;
}
.course-table tr:hover td { background: #f0f5ff; }
.course-table a { text-decoration: none; }
.course-table a:hover { text-decoration: underline; }

/* ── Course detail ── */
.breadcrumb { font-size: 0.9rem; color: #666; margin-bottom: 1.5rem; }
.breadcrumb a { color: #1b6ec2; text-decoration: none; }
.breadcrumb a:hover { text-decoration: underline; }

.course-detail-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 1rem;
    flex-wrap: wrap;
    margin-bottom: 1.5rem;
}
.course-detail-header h1 { margin: 0 0 0.3rem; font-size: 1.8rem; }
.dept-tag {
    display: inline-block;
    background: #e8f0fe;
    color: #1b6ec2;
    padding: 0.2rem 0.7rem;
    border-radius: 12px;
    font-size: 0.85rem;
    font-weight: 600;
}

.detail-grid {
    display: grid;
    grid-template-columns: 1fr 320px;
    gap: 2rem;
}
@media (max-width: 768px) { .detail-grid { grid-template-columns: 1fr; } }

.detail-main section { margin-bottom: 1.5rem; }
.detail-main h2 { font-size: 1.2rem; color: #1b3a5c; border-bottom: 2px solid #e8f0fe; padding-bottom: 0.3rem; margin-bottom: 0.8rem; }
.detail-main dl { display: grid; grid-template-columns: 130px 1fr; gap: 0.4rem 1rem; }
.detail-main dt { font-weight: 600; color: #555; }
.status-open { color: #26b050; font-weight: 600; }
.status-full { color: #e50000; font-weight: 600; }

.instructor-card {
    background: #f7f9fc;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.2rem;
}
.instructor-card h2 { font-size: 1.1rem; color: #1b3a5c; margin: 0 0 0.5rem; }
.instructor-card h3 { margin: 0 0 0.2rem; }
.instructor-title { color: #666; font-style: italic; margin: 0 0 0.8rem; }
.instructor-card dl { display: grid; grid-template-columns: 60px 1fr; gap: 0.3rem 0.5rem; margin-top: 1rem; font-size: 0.9rem; }
.instructor-card dt { font-weight: 600; color: #555; }

/* ── Enrollment form ── */
.enrollment-form-container {
    max-width: 600px;
